const matchItemToBatch = (itemSku, itemName, batchSku, batchName) => {
    const iSku = String(itemSku || '').trim().toLowerCase();
    const bSku = String(batchSku || '').trim().toLowerCase();
    const iName = String(itemName || '').trim().toLowerCase();
    const bName = String(batchName || '').trim().toLowerCase();

    const hasValidItemSku = iSku !== '' && iSku !== '-';
    
    if (hasValidItemSku) {
        return bSku === iSku;
    } else {
        return bName === iName;
    }
};

const calculatePromotions = (currentItems, allPromotions) => {
    let totalDiscount = 0;
    let newFreeItems = [];
    let appliedNames = [];
    
    const cleanItems = currentItems.filter(it => !it.desc.startsWith('[แถมฟรี]'));
    const subtotal = cleanItems.reduce((sum, it) => sum + (Number(it.price || it.sellPrice || it.buyPrice || 0) * Number(it.qty || 0)), 0);

    allPromotions.filter(p => p.isActive).forEach(promo => {
        if (promo.type === 'threshold_discount' || promo.type === 'shopee_voucher') {
            if (subtotal >= Number(promo.minAmount)) {
                totalDiscount += Number(promo.discountAmount);
                appliedNames.push(promo.name);
            }
        } 
        else if (promo.type === 'percentage_discount' || (promo.type === 'shopee_bundle' && promo.bundleType === 'percentage')) {
            let threshold = promo.type === 'shopee_bundle' ? (Number(promo.minQty) || 1) : Number(promo.minAmount);
            let meetsCondition = false;
            
            if (promo.type === 'shopee_bundle') {
                const totalQty = cleanItems.reduce((q, it) => q + Number(it.qty), 0);
                meetsCondition = totalQty >= threshold;
            } else {
                meetsCondition = subtotal >= threshold;
            }

            if (meetsCondition) {
                totalDiscount += (subtotal * Number(promo.discountPercentage)) / 100;
                appliedNames.push(promo.name);
            }
        } 
        else if (promo.type === 'shopee_bundle' && promo.bundleType === 'amount') {
            const totalQty = cleanItems.reduce((q, it) => q + Number(it.qty), 0);
            if (totalQty >= Number(promo.minQty)) {
                totalDiscount += Number(promo.discountAmount);
                appliedNames.push(promo.name);
            }
        }
        else if (promo.type === 'buy_x_get_y' || promo.type === 'shopee_addon') {
            const targetSku = promo.type === 'shopee_addon' ? promo.addonMainSku : promo.targetSku;
            const targetItem = cleanItems.find(it => (it.sku && it.sku !== '-' && it.sku === targetSku) || it.desc === targetSku);
            
            if (targetItem && Number(targetItem.qty) >= (Number(promo.minQty) || 1)) {
                const multiplier = Math.floor(Number(targetItem.qty) / (Number(promo.minQty) || 1));
                if (multiplier > 0) {
                    if (promo.type === 'buy_x_get_y') {
                        newFreeItems.push({
                            desc: `[แถมฟรี] ${promo.freeSku}`, sku: promo.freeSku, qty: multiplier * Number(promo.freeQty),
                            price: 0, sellPrice: 0, buyPrice: 0, unit: 'ชิ้น'
                        });
                        appliedNames.push(promo.name);
                    } else if (promo.type === 'shopee_addon') {
                        appliedNames.push(`Add-on: ${promo.name}`);
                    }
                }
            }
        }
    });

    return { totalDiscount, newFreeItems, appliedNames: [...new Set(appliedNames)] };
};

// --- 🔥 UPGRADED: AI Core Engine (Gemini 3.5 Flash) ---
const callGeminiAPI = async (prompt, isJson = true, imageBase64 = null) => {
    const userApiKey = localStorage.getItem('gemini_api_key');
    
    if (!userApiKey || userApiKey.trim() === "") {
        throw new Error("API_KEY_MISSING");
    }

    // --- 🔥 FIX: ใช้โมเดลล่าสุดของปี 2026 (Gemini 3.5 Flash) แทนโมเดล 1.5 ที่ถูกปิดตัวไปแล้ว ---
    const modelName = "gemini-3.5-flash"; 
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${userApiKey.trim()}`;

    const parts = [{ text: prompt }];
    
    // โหลดรูปภาพและระบุ MimeType อัตโนมัติ
    if (imageBase64) {
        const base64Data = imageBase64.includes(',') ? imageBase64.split(',')[1] : imageBase64;
        const mimeType = imageBase64.match(/data:(.*?);base64/)?.[1] || "image/jpeg";
        parts.push({ inlineData: { mimeType, data: base64Data } });
    }
    
    const payload = { 
        contents: [{ role: "user", parts }],
        generationConfig: {
            temperature: 0.3, // ปรับค่า 0.3 ให้ AI เน้นความแม่นยำของตัวเลข ลดการเดาสุ่ม
            topK: 40,
            topP: 0.95
        }
    };
    
    // บังคับให้ AI ส่งข้อมูลกลับมาเป็น JSON ตามโครงสร้างเป๊ะๆ
    if (isJson) {
        payload.generationConfig.responseMimeType = "application/json";
    }
    
    let delay = 1000;
    for (let i = 0; i < 5; i++) {
        try {
            const res = await fetch(url, { 
                method: 'POST', 
                headers: {'Content-Type': 'application/json'}, 
                body: JSON.stringify(payload) 
            });
            
            // อ่านข้อความ Error จากฝั่ง Google โดยตรงเพื่อนำมาแสดงผล
            if (!res.ok) {
                const errorData = await res.json().catch(() => ({}));
                throw new Error(`[API Error ${res.status}] ${errorData?.error?.message || res.statusText}`);
            }
            
            const data = await res.json();
            let text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
            
            if (isJson) {
                // ล้างอักขระขยะที่ AI อาจพ่นแถมมา เพื่อป้องกัน JSON.parse พัง
                text = text.replace(/```json/g, '').replace(/```/g, '').trim();
                return JSON.parse(text);
            }
            return text;
        } catch (e) {
            console.warn(`[Gemini AI] Attempt ${i + 1} Failed:`, e.message);
            
            if (e.message.includes('API_KEY_MISSING')) {
                throw new Error("กรุณาตั้งค่า API Key ของคุณในเมนู 'เครื่องมือขั้นสูง' ก่อนใช้งาน AI");
            }
            if (e.message.includes('[API Error 400]')) {
                throw new Error(`ส่งข้อมูลไม่สำเร็จ (HTTP 400) กรุณาตรวจสอบรูปภาพหรือข้อมูล: ${e.message}`);
            }
            if (e.message.includes('[API Error 403]')) {
                throw new Error(`API Key ไม่ถูกต้อง หรือไม่มีสิทธิ์การใช้งาน (HTTP 403)`);
            }
            if (e.message.includes('[API Error 404]')) {
                throw new Error(`ไม่พบโมเดล AI ในระบบ (HTTP 404): ${e.message}`);
            }
            
            if (i === 4) throw e;
            await new Promise(r => setTimeout(r, delay));
            delay *= 2; 
        }
    }
};

// --- 🔥 NEW: High-Speed OCR Cache & Client-Side Canvas Image Compressor ---
const ocrCacheMap = new Map();

const generateImageHashKey = (base64DataStr, fileSize, fileName) => {
  let hash = 0;
  const sampleStr = (base64DataStr || '').slice(-2000) + '_' + (fileSize || 0) + '_' + (fileName || '');
  for (let i = 0; i < sampleStr.length; i++) {
    const char = sampleStr.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return 'ocr_hash_' + Math.abs(hash);
};

const compressImageForOcr = (file, maxDimension = 1000, quality = 0.78) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;

        if (width > maxDimension || height > maxDimension) {
          if (width > height) {
            height = Math.round((height * maxDimension) / width);
            width = maxDimension;
          } else {
            width = Math.round((width * maxDimension) / height);
            height = maxDimension;
          }
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');

        // Draw image on white background
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);

        const imgData = canvas.toDataURL('image/jpeg', quality);
        resolve(imgData);
      };
      img.onerror = () => reject(new Error('ไม่สามารถประมวลผลไฟล์ภาพเพื่อย่อขนาดได้'));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error('อ่านไฟล์ล้มเหลว'));
    reader.readAsDataURL(file);
  });
};

const decryptPdfFallback = async (arrayBuffer, password) => {
    if (!window.pdfjsLib) {
        await new Promise((resolve) => {
            const s = document.createElement('script');
            s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
            s.onload = resolve; document.head.appendChild(s);
        });
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
    }
    if (!window.jspdf) {
        await new Promise((resolve) => {
            const s = document.createElement('script');
            s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
            s.onload = resolve; document.head.appendChild(s);
        });
    }

    const typedarray = new Uint8Array(arrayBuffer);
    const loadingTask = window.pdfjsLib.getDocument({ data: typedarray, password: password });
    const pdf = await loadingTask.promise;
    
    const pdfDoc = new window.jspdf.jsPDF('p', 'mm', 'a4');
    
    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale: 2.0 });
        
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;
        
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        await page.render({ canvasContext: ctx, viewport: viewport }).promise;
        
        const imgData = canvas.toDataURL('image/jpeg', 0.95);
        
        if (pageNum > 1) pdfDoc.addPage();
        
        const pdfWidth = pdfDoc.internal.pageSize.getWidth();
        const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
        
        pdfDoc.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
    }
    
    const pdfBase64 = pdfDoc.output('datauristring');
    return pdfBase64.split(',')[1];
};

