                    <StatCard title="จ่ายออกแล้ว (Cash Out)" value={analytics.cash.expense} color="rose" icon={<TrendingDown />} subtitle="รายจ่ายที่ชำระเงินแล้ว" trend={analytics.trends.cashExp} />
